package com.chainauth.security;
import com.chainauth.user.User; import com.chainauth.user.UserRepository; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.security.web.authentication.WebAuthenticationDetailsSource; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {
 private final JwtService jwt; private final CustomUserDetailsService users; private final UserRepository userRepository; public JwtAuthenticationFilter(JwtService jwt,CustomUserDetailsService users,UserRepository userRepository){this.jwt=jwt;this.users=users;this.userRepository=userRepository;}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{
  String header=req.getHeader("Authorization"); if(header!=null&&header.startsWith("Bearer ")&&SecurityContextHolder.getContext().getAuthentication()==null){try{String token=header.substring(7);String subject=jwt.subject(token);User account=userRepository.findByEmail(subject).orElseThrow();if(!account.isEnabled())throw new IllegalArgumentException("Account is disabled");if(jwt.tokenVersion(token)!=account.getTokenVersion())throw new IllegalArgumentException("Session has been revoked");UserDetails details=users.loadUserByUsername(subject);var auth=new UsernamePasswordAuthenticationToken(details,null,details.getAuthorities());auth.setDetails(new WebAuthenticationDetailsSource().buildDetails(req));SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception ignored){SecurityContextHolder.clearContext();}} chain.doFilter(req,res);
 }
}
